import { applyGate, type SingleGate, type Position } from '@qa/engine';
import { KET } from './format';

/** z, x and y axis pairs: the order the §8.2 table lists positions in. */
const READING_ORDER: readonly Position[] = ['ZERO', 'ONE', 'PLUS', 'MINUS', 'PLUS_I', 'MINUS_I'];

/**
 * The "Board effect" line of a gate card (ui-spec §8.2), generated by applying the gate to all
 * six positions and grouping the result into ↔ swaps, → cycles and the positions that stay.
 * Never typed by hand, so the card can never disagree with the engine.
 */
export function boardEffect(gate: SingleGate): string {
  const seen = new Set<Position>();
  const moves: string[] = [];
  const stays: string[] = [];
  for (const start of READING_ORDER) {
    if (seen.has(start)) continue;
    const cycle: Position[] = [start];
    seen.add(start);
    for (let p = applyGate(gate, start); p !== start; p = applyGate(gate, p)) {
      cycle.push(p);
      seen.add(p);
    }
    if (cycle.length === 1) stays.push(KET[start]!);
    else if (cycle.length === 2) moves.push(`${KET[cycle[0]!]} ↔ ${KET[cycle[1]!]}`);
    else moves.push([...cycle, start].map((p) => KET[p]).join(' → '));
  }
  if (moves.length === 0) return 'stays everywhere';
  return stays.length > 0 ? `${moves.join(', ')} · ${stays.join(', ')} stay` : moves.join(', ');
}
